messages.content:
Berikut manifest game edukasi penggolongan hewan dengan tema Cartoon dan tingkat kesulitan Santai. Saya memakai ukuran rintangan yang lebih sempit sesuai aturan kelayakan untuk kecepatan Santai (300).

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "hewan-pemakan-run", title: "Hewan Si Pemakan", seed: "hewan-pemakan-01",
  theme: { preset: "cartoon" },

  learning: {
    subject: "Ilmu Pengetahuan Alam",
    concept: "Penggolongan hewan berdasarkan jenis makanannya: herbivora, karnivora, omnivora",
    objectives: [
      "Mengelompokkan hewan ke dalam golongan herbivora, karnivora, dan omnivora",
      "Menjelaskan alasan penggolongan berdasarkan jenis makanan hewan"
    ],
    misconceptions: [
      "Semua hewan yang makan daging itu karnivora sejati, padahal ayam dan beruang juga makan tumbuhan sehingga omnivora"
    ],
    mode: "category",
    categories: [
      { id: "herbivora", label: "Herbivora", color: "#3FA34D" },
      { id: "karnivora", label: "Karnivora", color: "#E5484D" },
      { id: "omnivora",  label: "Omnivora",  color: "#F2A93B" }
    ],
    items: [
      { id: "sapi",     label: "Sapi",     category: "herbivora", explain: "Memakan rumput dan dedaunan sebagai sumber utama." },
      { id: "kambing",  label: "Kambing",  category: "herbivora", explain: "Pemakan tumbuhan dan daun." },
      { id: "kelinci",  label: "Kelinci",  category: "herbivora", explain: "Memakan sayuran, rumput, dan wortel." },
      { id: "harimau",  label: "Harimau",  category: "karnivora", explain: "Pemangsa daging hasil berburu." },
      { id: "singa",    label: "Singa",    category: "karnivora", explain: "Pemakan daging hasil berburu." },
      { id: "elang",    label: "Elang",    category: "karnivora", explain: "Burung pemangsa yang memakan daging." },
      { id: "ayam",     label: "Ayam",     category: "omnivora",  explain: "Makan biji-bijian sekaligus cacing dan serangga." },
      { id: "babi",     label: "Babi",     category: "omnivora",  explain: "Makan tumbuhan maupun makanan hewani." },
      { id: "beruang",  label: "Beruang",  category: "omnivora",  explain: "Makan buah, ikan, dan hewan kecil." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 5, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 300, maxSpeed: 600, accel: 4 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",  w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "semak", w: 90, h: 40, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 20, speed: 20 }
  }
});
// END_OF_MANIFEST
```

Game ini mengajak pemain mengambil hewan yang cocok dengan target golongan (herbivora, karnivora, omnivora) sambil menghindari batu dan semak. Asumsi penting: item hewan muncul sebagai objek yang diambil, dan penjelasan singkat tampil otomatis saat salah ambil.
